const rate = 2;

function makePricer(rate) {
  return (price) => price * rate;
}

function quote(pricer) {
  const rate = 100;

  return pricer(5);
}

const plain = (price) => price * rate;

console.log(quote(makePricer(3)));
console.log(quote(plain));
console.log(quote((price) => price + rate));
